sys_script.script:
(function executeRule(current, previous) {
  var HEADER_TABLE       = 'x_1797098_pettyc_0_pettycashmain';
  var LINES_TABLE        = 'x_1797098_pettyc_0_pettycashlines';
  var REF_TO_HEADER      = 'pettycashmain_ref';
  var LINE_AMOUNT_FIELD  = 'total_line_amount';
  var HEADER_TOTAL_FIELD = 'total_line_amount';

  var headersToRecalc = {};

  // new/current header (insert/update)
  if (current.operation() !== 'delete') {
    var curHdr = current.getValue(REF_TO_HEADER);
    if (curHdr) headersToRecalc[curHdr] = true;
  }

  // previous/old header (delete or ref changed)
  var prevHdr = previous ? previous.getValue(REF_TO_HEADER) : '';
  var refChanged = previous && current.operation() === 'update' &&
                   current.getValue(REF_TO_HEADER) !== prevHdr;
  if (current.operation() === 'delete' && prevHdr) headersToRecalc[prevHdr] = true;
  if (refChanged && prevHdr) headersToRecalc[prevHdr] = true;

  function recalcAndUpdate(headerSysId) {
    var ga = new GlideAggregate(LINES_TABLE);
    ga.addQuery(REF_TO_HEADER, headerSysId);
    ga.addAggregate('SUM', LINE_AMOUNT_FIELD);
    ga.query();

    var total = 0;
    if (ga.next()) total = parseFloat(ga.getAggregate('SUM', LINE_AMOUNT_FIELD) || 0) || 0;

    var hdr = new GlideRecord(HEADER_TABLE);
    if (hdr.get(headerSysId)) {
      hdr.setWorkflow(false);
      hdr.setUseEngines(false);
      hdr.setValue(HEADER_TOTAL_FIELD, total);
      hdr.update();
    }
  }

  for (var id in headersToRecalc) if (headersToRecalc[id]) recalcAndUpdate(id);

})(current, previous);

